<script setup lang="ts">
import{onUnmounted,ref,watch}from'vue';import type{MixConfig}from'../../core/models';import type{MixResult}from'../../ports/audio-mixer.port';
const props=defineProps<{duration:number;config:MixConfig;hasBackground:boolean;backgroundName:string;backgroundDuration:number;result?:MixResult;mixing:boolean;clipRisk:boolean;stale:boolean}>();
const emit=defineEmits<{import:[file:File];patch:[p:Partial<MixConfig>];preview:[];reduce:[];confirm:[];skip:[];revert:[]}>();
const url=ref('');watch(()=>props.result,(r)=>{if(url.value)URL.revokeObjectURL(url.value);url.value=r&&typeof URL.createObjectURL==='function'?URL.createObjectURL(r.blob):''},{immediate:true});onUnmounted(()=>{if(url.value)URL.revokeObjectURL(url.value)});
const num=(e:Event)=>Number((e.target as HTMLInputElement).value);
</script>
<template><section class="stage-card"><span class="kicker">03 / MIX DESK</span><h2>给人声铺一层背景</h2><p class="mix-hint">当前人声选段 {{ duration.toFixed(1) }}s，成品以人声长度为准，最长 10 秒。原始人声保留，可随时撤回。</p><label class="bg-import">导入背景音频<input data-testid="bg-input" type="file" accept="audio/*" @change="($event.target as HTMLInputElement).files?.[0] && emit('import', ($event.target as HTMLInputElement).files![0])"></label><template v-if="hasBackground"><p class="mix-status"><span>背景：{{ backgroundName }}（{{ backgroundDuration.toFixed(1) }}s）</span><span v-if="stale">配置已修改，重新生成后试听才会更新</span></p><div class="mix-grid"><label>背景起播位置 {{ config.backgroundStart.toFixed(1) }}s<input type="range" min="0" :max="Math.max(0,backgroundDuration-.1)" step=".1" :value="config.backgroundStart" @input="emit('patch',{backgroundStart:num($event)})"></label><label>人声音量 {{ Math.round(config.voiceGain*100) }}%<input type="range" min="0" max="1" step=".05" :value="config.voiceGain" @input="emit('patch',{voiceGain:num($event)})"></label><label>背景音量 {{ Math.round(config.backgroundGain*100) }}%<input type="range" min="0" max="1" step=".05" :value="config.backgroundGain" @input="emit('patch',{backgroundGain:num($event)})"></label><label>有人声时背景降低 {{ Math.round(config.duckAmount*100) }}%<input type="range" min="0" max="1" step=".05" :value="config.duckAmount" @input="emit('patch',{duckAmount:num($event)})"></label><label>停顿后恢复 {{ config.duckRelease.toFixed(1) }}s<input type="range" min=".1" max="2" step=".1" :value="config.duckRelease" @input="emit('patch',{duckRelease:num($event)})"></label><label>整体音量 {{ Math.round(config.masterGain*100) }}%<input type="range" min=".05" max="1" step=".05" :value="config.masterGain" @input="emit('patch',{masterGain:num($event)})"></label></div><label class="loop-toggle"><input type="checkbox" :checked="config.loop" @change="emit('patch',{loop:($event.target as HTMLInputElement).checked})"> 背景不足时循环播放（接缝平滑过渡）</label><div class="mix-actions"><button data-testid="preview-mix" class="acid-button" type="button" :disabled="mixing" @click="emit('preview')">{{ mixing?'混音中…':'生成试听' }}</button><button v-if="result" data-testid="revert-mix" class="ghost-button" type="button" @click="emit('revert')">撤回，恢复原始人声</button></div><div v-if="clipRisk" class="clip-warning" data-testid="clip-warning"><span>混音峰值 {{ result?.peak.toFixed(2) }} 超出可表达音量，直接导出会削波。请整体降低音量（两路比例保持不变）后再导出。</span><button data-testid="reduce-gain" type="button" @click="emit('reduce')">整体降低音量</button></div><div v-if="result&&!clipRisk" class="mix-player"><audio data-testid="mix-player" controls :src="url"></audio><p>试听的即为确认后的混音，情绪分析与保存都使用它。</p></div><button data-testid="confirm-mix" class="acid-button" type="button" :disabled="clipRisk||mixing" @click="emit('confirm')">确认混音，分析情绪 →</button></template><button data-testid="skip-mix" class="ghost-button" type="button" @click="emit('skip')">不加背景，直接分析 →</button></section></template>
